function portrait(h){const i=HEROES.findIndex(x=>x.id===h.id),c=h.color||'#85c7b8';const heads=[`<path d="M74 43L87 18 104 36 123 18 132 44 123 68H85Z"/>`,`<path d="M65 60L52 12 87 37 102 20 119 37 153 12 140 64 122 82 82 82Z"/>`,`<path d="M56 43L79 35 90 14 119 14 130 36 154 43Z"/><ellipse cx="105" cy="59" rx="24" ry="27"/>`,`<path d="M68 49L65 27 87 32 103 24 121 32 144 27 140 51 132 80 78 80Z"/>`,`<path d="M74 43L65 15 88 29 104 19 122 29 143 15 135 43 124 78 85 78Z"/>`,`<path d="M74 43L52 14 57 1 85 26 103 22 125 26 151 1 156 14 134 43 125 77 85 77Z"/>`,`<path d="M67 73Q67 12 105 15Q144 15 143 73L126 62 119 43 90 43 81 64Z"/>`,`<path d="M76 40L86 17 104 6 124 17 134 40 124 75 87 75Z"/><path d="M65 18L46 5 61 41M145 18L163 5 149 41" fill="none" stroke="${c}" stroke-width="5"/>`,`<path d="M70 46L56 20 75 28 87 10 105 23 122 10 135 28 153 20 139 46 129 80 81 80Z"/>`,`<path d="M72 40L41 21 38 1 62 20 88 24 103 18 122 24 147 20 170 1 168 21 136 40 129 79 80 79Z"/>`,`<path d="M68 69Q56 41 84 18L82 0 101 17 114 4 119 24Q154 38 139 81L123 74 125 42 84 42 85 76Z"/>`];return `<svg viewBox="0 0 210 150" aria-hidden="true"><defs><linearGradient id="g-${h.id}" x2="0" y2="1"><stop stop-color="${c}"/><stop offset="1" stop-color="#16252d"/></linearGradient></defs><g fill="url(#g-${h.id})" stroke="${c}" stroke-width="1.1"><path d="M44 149L49 103 80 81 85 69H125L130 81 162 103 168 149Z"/><path d="M49 102L23 130 31 149H79L84 98 65 83Z"/><path d="M161 102L188 130 180 149H131L126 98 145 83Z"/>${heads[Math.max(0,i)]}<path d="M88 49L101 52 96 57 87 53M122 49L109 52 114 57 123 53" fill="#e8f7e3" stroke="none"/><path d="M91 70L104 81 118 70 114 98 104 111 95 98Z" fill="#12232b" opacity=".6"/><path d="M80 112L104 125 129 112M69 133L105 145 142 133" fill="none" opacity=".7"/></g></svg>`}
function heroCard(h,index,extra=''){const def=byId(h.id),s=getStats(h);return `<button class="hero-card ${extra}" data-hero="${h.id}" style="--hero:${def.color}55"><div class="portrait">${portrait(def)}<span class="card-pos">${index<2?'FRONT':'BACK'} ${String(index+1).padStart(2,'0')}</span><span class="card-level">LV.${h.level}</span></div><div class="hero-card-content"><h3>${def.name}</h3><p>${roleLabel(h)} <span class="tag">· ${h.profession}</span></p><div class="mini-bar"><i style="width:100%"></i></div><div class="card-bottom"><span>♥ ${s.hp}</span><span>⚔ ${s.attack}</span><span>◇ ${s.armor.toFixed(0)}</span></div></div></button>`}
function renderUI(){$('#gold').textContent=game.gold;$('#essence').textContent=game.essence;$('#floor').textContent=String(Math.min(game.floor,15)).padStart(2,'0');$('#floor-title').textContent=game.completed?'远征已完成':names[game.floor-1];$('#floor-desc').textContent=game.floor%3===0?'首领层 · 史诗战利品必定掉落':'普通层 · 获取金币、经验与装备';$('#floor-track').innerHTML=Array.from({length:15},(_,i)=>`<span class="floor-step ${i+1<=game.cleared?'done':i+1===game.floor?'current':''}" title="第 ${i+1} 层${(i+1)%3===0?' · 首领':''}">${i+1<=game.cleared?'✓':(i+1)%3===0?'♜':i+1}</span>`).join('');$('#party').innerHTML=game.party.map((id,i)=>heroCard(game.roster.find(h=>h.id===id),i)).join('');$$('#party [data-hero]').forEach(el=>el.onclick=()=>openHero(el.dataset.hero));$('#start').disabled=running();$('#start-top').disabled=running();$('#start-top').textContent=game.completed?'凯旋 ✧':battle?.status==='lost'?'再战 ↻':battle?.status==='won'?'下一层 →':'开战 →';$('#start').innerHTML=game.completed?'远征凯旋 ✧':battle?.status==='lost'?'重新挑战 <span>↻</span>':battle?.status==='won'?'进入下一层 <span>→</span>':'开始战斗 <span>→</span>';$('#phase').textContent=running()?(paused?'战斗已暂停':'战斗进行中'):battle?.status==='won'?'本层胜利':battle?.status==='lost'?'远征受挫':'战前部署';$('#pause').disabled=!running();$('#pause').textContent=paused?'继续':'暂停';$('#edit-party').disabled=running();}
function openModal(content){returnFocus=document.activeElement;$('#modal-content').innerHTML=content;$('#modal').classList.remove('hidden');$('#close-modal').focus()}
