$('#close-modal').onclick=closeModal;$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key===' '&&e.target===document.body&&running()){e.preventDefault();togglePause()}if(e.key==='Tab'&&!$('#modal').classList.contains('hidden')){const items=$$('#modal button:not(:disabled),#modal select:not(:disabled),#modal input:not(:disabled)');const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
function option(value,label,current){return `<option value="${escape(value)}" ${value===current?'selected':''}>${escape(label)}</option>`}
function targetOptions(current,action){const allied=action==='protect';return (allied?[['lowest_ally','生命比例最低的队友']]:[['front','最前排敌人'],['back','最后排敌人'],['lowest_hp','生命比例最低敌人'],['strongest','攻击最高的敌人']]).map(([v,l])=>option(v,l,current)).join('')+(allied?game.party.map(id=>option(id,`队友 · ${byId(id).name}`,current)).join(''):Array.from({length:5},(_,i)=>option(`e${i}`,`敌方位置 ${i+1}`,current)).join(''))}
function openHero(id){modalHero=id;const h=game.roster.find(x=>x.id===id),d=byId(id),s=getStats(h),inParty=game.party.indexOf(id),lock=running()?'disabled':'';openModal(`<p class="eyebrow">HERO DOSSIER / 英雄档案</p><h2>${d.name} <small style="font:13px sans-serif;color:#99aaa9">LV.${h.level}</small></h2><p>${d.desc}</p>${running()?'<div class="hint-box">战斗中仅可查看。战后可调整专精、装备与战术。</div>':''}<div class="modal-grid"><div><div class="hero-detail-art" style="--hero:${d.color}40">${portrait(d)}</div><div class="stat-grid"><div><b>${s.hp}</b>生命值</div><div><b>${s.attack}</b>攻击力</div><div><b>${s.armor.toFixed(1)}</b>护甲</div></div><div class="form-row"><label>专精</label><select id="hero-spec" ${lock}>${d.specs.map(x=>option(x,x,h.spec)).join('')}</select><label>职业</label><select id="hero-prof" ${lock}>${['工匠','珠宝师','辩手'].map(x=>option(x,x,h.profession)).join('')}</select></div><p class="small-note">工匠打造护甲与武器；珠宝师打造饰品；辩手提供商店八折与开战护盾。</p><div class="progress-fill"><i style="width:${Math.min(100,h.xp/(h.level*70)*100)}%"></i></div><p class="small-note">经验 ${h.xp} / ${h.level*70} · 上阵参战即可获得经验</p><div class="modal-actions"><button class="secondary" id="train" ${lock}>训练升级 · ${35+h.level*15} 金币</button>${inParty>=0?`<button class="secondary" id="move-left" ${lock} ${inParty===0?'disabled':''}>← 站位前移</button><button class="secondary" id="move-right" ${lock} ${inParty===4?'disabled':''}>站位后移 →</button>`:''}</div><h3>装备 · ${Object.keys(h.equipment).length} / 7</h3><div class="equip-grid">${SLOTS.map(slot=>`<div class="equip-item">${SLOT_NAMES[slot]}<b style="color:${h.equipment[slot]?.color||'#71898c'}">${h.equipment[slot]?.name||'空置'}</b></div>`).join('')}</div><button class="secondary" id="hero-equip" style="margin-top:12px" ${lock}>从背包装备 ↗</button></div><div><h3>战术规则 <span style="font-size:10px;color:#8fa29f">条件 → 动作 → 目标</span></h3><p>同类动作按列表顺序匹配。没有匹配规则时普攻前排；大招规则未满足时会保留大招。</p><div id="rules">${h.rules.map((r,i)=>`<div class="rule" data-rule="${i}"><input type="checkbox" aria-label="启用规则 ${i+1}" class="rule-enabled" ${r.enabled!==false?'checked':''} ${lock}><select class="rule-condition" ${lock}>${[['always','始终'],['low_hp','自身生命 < 45%'],['enemy_cast','有敌人法力 ≥ 80%']].map(([v,l])=>option(v,l,r.condition)).join('')}</select><select class="rule-action-select" ${lock}>${[['focus','普攻集火'],['ultimate','施放大招'],['protect','保护 / 治疗']].map(([v,l])=>option(v,l,r.action)).join('')}</select><button class="rule-remove" aria-label="删除规则 ${i+1}" ${lock}>×</button><select class="rule-action rule-target" ${lock}>${targetOptions(r.target,r.action)}</select></div>`).join('')}</div><div class="modal-actions"><button class="secondary" id="add-rule" ${lock} ${h.rules.length>=8?'disabled':''}>+ 添加规则</button><button class="secondary" id="focus-back" ${lock}>预设：切后排</button><button class="secondary" id="protect-front" ${lock}>预设：保护前排</button></div><div class="hint-box">推荐：让神谕者保护前排坦克，让输出优先击杀敌方暗巫。专精与装备会改变真实战斗计算。</div><p class="small-note">原型规则最多 8 条。前两位为前排，其余为后排。自动变阵、宝石镶嵌、完整俱乐部联网将在后续版本扩展。</p></div></div>`);modalHero=id;
$('#hero-spec').onchange=e=>{h.spec=e.target.value;save();renderUI();openHero(id)};$('#hero-prof').onchange=e=>{h.profession=e.target.value;save();renderUI();openHero(id)};$('#train').onclick=()=>{if(act(trainHero(game,id)))openHero(id)};$('#move-left')?.addEventListener('click',()=>swapPosition(inParty,inParty-1,id));$('#move-right')?.addEventListener('click',()=>swapPosition(inParty,inParty+1,id));$('#hero-equip').onclick=()=>openForge('inventory',id);$$('#rules .rule').forEach(row=>{const i=Number(row.dataset.rule);row.querySelector('.rule-enabled').onchange=e=>{h.rules[i].enabled=e.target.checked;save()};row.querySelector('.rule-condition').onchange=e=>{h.rules[i].condition=e.target.value;save()};row.querySelector('.rule-action-select').onchange=e=>{h.rules[i].action=e.target.value;h.rules[i].target=e.target.value==='protect'?'lowest_ally':'front';save();openHero(id)};row.querySelector('.rule-target').onchange=e=>{h.rules[i].target=e.target.value;save()};row.querySelector('.rule-remove').onclick=()=>{h.rules.splice(i,1);save();openHero(id)}});$('#add-rule').onclick=()=>{h.rules.push({condition:'always',action:'focus',target:'front',enabled:true});save();openHero(id)};$('#focus-back').onclick=()=>{h.rules=[{condition:'always',action:'focus',target:'back',enabled:true},{condition:'always',action:'ultimate',target:'back',enabled:true}];save();openHero(id);toast('已配置切后排战术')};$('#protect-front').onclick=()=>{h.rules=[{condition:'always',action:'protect',target:game.party[0],enabled:true}];save();openHero(id);toast('已配置保护首位英雄')};}
function swapPosition(a,b,id){if(running()||b<0||b>4)return;[game.party[a],game.party[b]]=[game.party[b],game.party[a]];save();renderUI();openHero(id);toast('站位已调整')}
let partyDraft=[];function openRoster(){if(running()){toast('请等战斗结束后调整阵容');return}partyDraft=[...game.party];drawRoster()}
function drawRoster(){openModal(`<p class="eyebrow">THE COMPANY / 组建远征队</p><h2>每个英雄，都有自己的答案。</h2><p>选择恰好 5 名英雄。先取消一名，再选择替补；前两名会站在前排。</p><div class="hint-box">已选 ${partyDraft.length} / 5：${partyDraft.map(id=>byId(id).name).join(' → ')||'请选择英雄'}</div><div class="roster-grid">${game.roster.map((h,i)=>heroCard(h,Math.max(0,partyDraft.indexOf(h.id)),partyDraft.includes(h.id)?'chosen':'')).join('')}</div><div class="modal-actions"><button class="primary" id="confirm-party" ${partyDraft.length!==5?'disabled':''}>确认阵容 →</button><button class="secondary" id="balanced-party">推荐均衡阵容</button></div>`);$$('.roster-grid [data-hero]').forEach(el=>el.onclick=()=>{const id=el.dataset.hero;if(partyDraft.includes(id))partyDraft=partyDraft.filter(x=>x!==id);else if(partyDraft.length<5)partyDraft.push(id);else{toast('队伍已满，请先取消一名英雄');return}drawRoster()});$('#confirm-party').onclick=()=>{if(partyDraft.length!==5)return;game.party=[...partyDraft];save();renderUI();closeModal();toast('远征队整装待发')};$('#balanced-party').onclick=()=>{partyDraft=['centaur','juggernaut','shadowfiend','lina','oracle'];drawRoster()}}
function statText(stats){return Object.entries(stats).map(([k,v])=>`${{hp:'生命',attack:'攻击',armor:'护甲',haste:'攻速'}[k]||k} +${k==='haste'?Math.round(v*100)+'%':v}`).join(' · ')}
function itemCard(item,body){return `<div class="item-card" style="border-color:${item.color}77"><h4 style="color:${item.color}">${escape(item.name)}</h4><p>${item.rarity} · ${SLOT_NAMES[item.slot]} · 装备等级 ${item.level}</p><p>${statText(item.stats)}</p>${body}</div>`}
function openForge(tab='inventory',heroId=game.party[0]){forgeTab=tab;const lock=running()?'disabled':'';openModal(`<p class="eyebrow">THE FORGE / 工坊与补给</p><h2>为下一场胜利，做些准备。</h2><p>金币 <b style="color:var(--gold)">${game.gold}</b> · 余烬 <b style="color:var(--gold)">${game.essence}</b> · 装备可在英雄之间反复换装，替换后旧装备返回背包。</p>${running()?'<div class="hint-box">战斗期间仅可查看，战后再进行装备与交易。</div>':''}<div class="tab-row"><button data-forge="inventory" class="${tab==='inventory'?'active':''}">背包 · ${game.inventory.length}</button><button data-forge="craft" class="${tab==='craft'?'active':''}">打造装备</button><button data-forge="shop" class="${tab==='shop'?'active':''}">旅行商人</button></div><div id="forge-body"></div>`);$$('[data-forge]').forEach(el=>el.onclick=()=>openForge(el.dataset.forge,heroId));if(tab==='inventory'){$('#forge-body').innerHTML=`<div class="form-row"><label>装备给</label><select id="equip-hero" ${lock}>${game.roster.map(h=>option(h.id,`${byId(h.id).name} · Lv.${h.level}`,heroId)).join('')}</select><span class="small-note">同部位自动替换</span></div><div class="inventory">${game.inventory.map(item=>itemCard(item,`<button data-equip="${item.id}" ${lock}>装备给此英雄 ↗</button>`)).join('')||'<p>背包暂时为空。赢得战斗、打造或购买装备。</p>'}</div>`;$$('[data-equip]').forEach(el=>el.onclick=()=>{const id=$('#equip-hero').value;if(act(equipItem(game,id,el.dataset.equip)))openForge('inventory',id)})}else if(tab==='craft'){$('#forge-body').innerHTML=`<div class="hint-box">上阵工匠可打造护甲与武器，上阵珠宝师可打造饰品。打造保底稀有，30% 史诗、8% 传说。神器仅在远征里程碑出现。</div><div class="inventory">${SLOTS.map(slot=>`<div class="item-card"><h4>${SLOT_NAMES[slot]}</h4><p>${slot.startsWith('trinket')?'珠宝师':'工匠'}专属</p><p>需要 ${slot.startsWith('trinket')?5:6} 余烬</p><button data-craft="${slot}" ${lock}>⚒ 开始打造</button></div>`).join('')}</div>`;$$('[data-craft]').forEach(el=>el.onclick=()=>{if(act(craftItem(game,el.dataset.craft)))openForge('inventory',heroId)})}else{$('#forge-body').innerHTML=`<div class="hint-box">${game.party.some(id=>game.roster.find(h=>h.id===id).profession==='辩手')?'辩手交涉生效：全部商品享受八折。':'上阵辩手可获得八折价格，并给全队开战增益。'}每层更新货品，可重复购买。</div><div class="inventory">${generateShop(game).map((item,i)=>itemCard(item,`<button data-buy="${i}" ${lock}>购买 · ${shopPrice(game,item)} 金币</button>`)).join('')}</div>`;$$('[data-buy]').forEach(el=>el.onclick=()=>{if(act(buyItem(game,generateShop(game)[Number(el.dataset.buy)])))openForge('shop',heroId)})}}
function openClub(){openModal(`<p class="eyebrow">THE LEAGUE / 俱乐部概念预览</p><h2>远征之外，还有更大的舞台。</h2><div class="hint-box">本 demo 重点实现 PVE 战斗与成长。这里是 <b>AI 对手的单日杯赛演示</b>，不是真人联网比赛，不发放正式联赛奖励。</div><p>让当前五人小队参加三轮淘汰赛。结果由相同战斗引擎即时模拟；不消耗资源，也不会更改爬塔进度。</p><div class="bracket" id="bracket"><div><h3>八强赛</h3><div class="match">你的远征队<br>vs 灰羽俱乐部</div></div><div><h3>半决赛</h3><div class="match">等待八强赛结果</div></div><div><h3>冠军赛</h3><div class="match">等待半决赛结果</div></div></div><button class="primary" id="run-cup">模拟单日杯赛 →</button><p class="small-note">瑞士轮、双败赛、联赛、声望与选秀权属于完整设计，未在此原型中实现。</p>`);$('#run-cup').onclick=()=>{const g=deserialize(serialize(game));let won=true;const results=[];for(let i=0;i<3;i++){if(!won){results.push({skipped:true});continue}g.floor=Math.max(1,Math.min(15,game.floor-1+i*2));g.rng=20261031+i*99;const b=startBattle(g);for(let t=0;t<1500&&b.status==='running';t++)tickBattle(b,.1);won=b.status==='won';results.push({won,time:b.time,floor:g.floor})}$('#bracket').innerHTML=results.map((r,i)=>`<div><h3>${['八强赛','半决赛','冠军赛'][i]}</h3><div class="match">${r.skipped?'未晋级':`你的远征队<br>vs ${['灰羽俱乐部','星火战团','永夜学院'][i]}<br><b class="${r.won?'winner':''}">${r.won?'胜利':'落败'} · ${r.time.toFixed(1)} 秒</b>`}</div></div>`).join('');$('#run-cup').textContent=won?'冠军！再模拟一次 ↻':'调整阵容后再来 ↻'}}
function showHelp(){openModal(`<p class="eyebrow">FIELD GUIDE / 远征手册</p><h2>先赢一场，再创造你的流派。</h2><div class="hint-box">1. 点击「开始战斗」，五人小队会自动战斗。<br>2. 点击敌人，可以让全队立即集火它。<br>3. 胜利获得经验、金币、余烬与装备。点击英雄升级、切换专精和配置战术。<br>4. 每三层挑战首领，完成第十五层赢得远征。</div><h3>把策略变成优势</h3><p>前两位是前排，其余为后排。神谕者适合保护坦克，远程输出可以优先打后排暗巫。每位英雄都支持「条件 → 动作 → 目标」规则，大招也可以保留至条件满足。点击英雄卡片开始调整。</p><h3>成长与失败</h3><p>失败无资源惩罚，可以免费重试；调整阵容、花金币训练、打造或购入装备均能突破难关。装备不会自动穿戴，请在工坊选择英雄后装备。重开远征需要确认，会清除当前进度。</p><h3>原型边界</h3><p>所有英雄与属性均为玩法验证数值，不是 Dota 2 正式服数据。11 位英雄含专精改造；联网 PVP、自动变阵、宝石系统与正式联赛暂未实现。俱乐部杯赛为 AI 模拟。进度仅保存在当前浏览器。</p><p class="small-note">3D 战场：拖动旋转、滚轮缩放、点击重置镜头；可随时切换 2D 战术视图与省电画质。快捷键：空格暂停 / 继续战斗，Esc 关闭面板。战斗在切换浏览器标签页后会自动暂停。</p>`)}
$('#help').onclick=showHelp;$('#edit-party').onclick=openRoster;$$('[data-view]').forEach(el=>el.onclick=()=>{if(el.dataset.view==='battle'){closeModal();return}$$('[data-view]').forEach(x=>x.classList.toggle('active',x===el));if(el.dataset.view==='roster')openRoster();if(el.dataset.view==='forge')openForge();if(el.dataset.view==='club')openClub()});
$('#reset').onclick=()=>{if(running()){toast('请先完成当前战斗');return}openModal(`<p class="eyebrow">NEW EXPEDITION</p><h2>开启一段新的远征？</h2><p>这会清除当前浏览器中的英雄成长、装备和爬塔进度，无法撤销。</p><div class="modal-actions"><button id="confirm-reset" class="primary">确认重新开始</button><button id="cancel-reset" class="secondary">保留当前进度</button></div>`);$('#cancel-reset').onclick=closeModal;$('#confirm-reset').onclick=()=>{game=createGame(Date.now()%4294967296);battle=null;fx=[];save();renderUI();$('#battle-overlay').classList.add('hidden');closeModal();toast('新的远征，新的可能。')}};
$('#speed').onclick=()=>{speed=speed===1?2:speed===2?4:1;$('#speed').textContent=`${speed}×`};function togglePause(){if(!running())return;paused=!paused;renderUI()}$('#pause').onclick=togglePause;$('#log-toggle').onclick=()=>$('#battle-log').classList.toggle('hidden');document.addEventListener('visibilitychange',()=>{if(document.hidden&&running()){paused=true;renderUI()}});
$('#start').onclick=()=>{if(running())return;if(game.completed){openModal(`<p class="eyebrow">ASCENT COMPLETE</p><h2>你已征服灰烬之塔。</h2><p>十五层远征已完成。你可以继续研究英雄与装备，参加 AI 杯赛，或从页面右上角开启新远征。</p>`);return}battle=startBattle(game);paused=false;lastSeen=0;fx=[];selected=null;save();$('#battle-overlay').classList.add('hidden');$('#battle-hint').textContent='点击敌人实时集火 · 空格暂停 · 倍速可随时调整';renderUI()};
$('#start-top').onclick=()=>$('#start').click();
function finishBattle(){const reward=settleBattle(game,battle);if(!reward.ok)return;save();renderUI();const won=battle.status==='won';const best=Object.entries(battle.damage).filter(([uid])=>uid.startsWith('a-')).sort((a,b)=>b[1]-a[1])[0];const mvp=best?battle.units.find(u=>u.uid===best[0]):null;$('#battle-overlay').innerHTML=`<div class="reward-icon">${won?'✧':'◇'}</div><p class="eyebrow">${won?'VICTORY / 胜利':'REGROUP / 重整旗鼓'}</p><h2>${reward.completed?'长夜已尽，余烬不灭。':won?'又一层，被你征服。':'下一次，换一种策略。'}</h2><p>${won?`金币 +${reward.gold}　余烬 +${reward.essence}　经验 +${reward.xp}<br><span style="color:${reward.item?.color}">${reward.item?.name||''}</span>${reward.bonusItem?` · ${reward.bonusItem.name}`:''} 已进入背包`:'本次挑战不扣除资源。<br>试试升级前排、装备新武器，或优先集火敌方后排。'}</p>${mvp?`<p style="font-size:10px">本场输出之星 · ${mvp.name} · ${Math.round(best[1])} 伤害</p>`:''}<button id="inspect-loot" class="secondary">${won?'整备装备 ↗':'调整战术 ↗'}</button>`;$('#battle-overlay').classList.remove('hidden');$('#inspect-loot').onclick=()=>won?openForge():openHero(game.party[0]);$('#battle-hint').textContent=won?'奖励已自动领取。先整备装备，再继续向上。':'失败无惩罚。调整阵容与成长后可再次挑战。'}
function previewUnits(){return [...game.party.map((id,i)=>{const h=game.roster.find(x=>x.id===id),d=byId(id),s=getStats(h);return {...d,...h,...s,uid:`a-${id}`,team:'ally',position:i,maxHp:s.hp,mana:25,maxMana:100,shield:0}}),...enemiesForFloor(Math.min(15,game.floor))]}
function coords(u){const front=u.position<2;const x=u.team==='ally'?(front?.35:.15):(front?.65:.85);const ys=front?[.35,.68]:[.20,.49,.78];return {x:x*W,y:ys[front?u.position:u.position-2]*H}}
function rgba(hex,a){if(!hex||hex[0]!=='#')return `rgba(140,190,170,${a})`;return `rgba(${parseInt(hex.slice(1,3),16)},${parseInt(hex.slice(3,5),16)},${parseInt(hex.slice(5,7),16)},${a})`}
function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;DPR=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(W*DPR);canvas.height=Math.round(H*DPR);ctx.setTransform(DPR,0,0,DPR,0,0)}new ResizeObserver(resize).observe(canvas);
function drawArena(t){ctx.clearRect(0,0,W,H);ctx.save();ctx.strokeStyle='#acbba011';ctx.lineWidth=1;const center=W/2;for(let i=-9;i<10;i++){ctx.beginPath();ctx.moveTo(center+i*W*.085,0);ctx.lineTo(center+i*W*.18,H);ctx.stroke()}for(let i=0;i<8;i++){const y=30+i*i*7;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.strokeStyle='#a4bd9920';ctx.beginPath();ctx.ellipse(center,H*.54,W*.27,H*.37,0,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.ellipse(center,H*.54,W*.23,H*.31,0,0,Math.PI*2);ctx.stroke();ctx.setLineDash([3,12]);ctx.strokeStyle='#c9b87c22';ctx.beginPath();ctx.moveTo(center,55);ctx.lineTo(center,H-32);ctx.stroke();ctx.setLineDash([]);for(let i=0;i<28;i++){const px=((i*137.31)%W),py=((i*89.83+t*(i%3+1)*.003)%H);ctx.fillStyle=i%2?'#b9ccab29':'#e9ca8b38';ctx.beginPath();ctx.arc(px,py,i%3===0?1.3:.7,0,7);ctx.fill()}ctx.restore();const units=battle?battle.units:previewUnits();hitboxes=[];units.forEach(u=>drawUnit(u,t));drawFx(t,units)}
function drawUnit(u,t){const p=coords(u),small=W<600||H<350,r=small?18:26;const dead=u.hp<=0;const hurt=fx.some(f=>f.target===u.uid&&f.type==='damage'&&t-f.created<150);const active=fx.some(f=>f.source===u.uid&&f.type==='skill'&&t-f.created<700);ctx.save();ctx.translate(p.x,p.y);if(dead)ctx.globalAlpha=.26;const col=u.color||'#9c7080';const glow=ctx.createRadialGradient(0,0,1,0,0,r*2.5);glow.addColorStop(0,rgba(col,active?.45:.14));glow.addColorStop(1,rgba(col,0));ctx.fillStyle=glow;ctx.beginPath();ctx.arc(0,0,r*2.5,0,7);ctx.fill();ctx.fillStyle='#0d181f';ctx.strokeStyle=selected===u.uid?'#f3d29a':rgba(col,.65);ctx.lineWidth=selected===u.uid?2:1;ctx.beginPath();ctx.ellipse(0,r*.9,r*1.2,r*.35,0,0,7);ctx.fill();ctx.stroke();if(active){ctx.strokeStyle=rgba(col,.7);ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,-r*.15,r*1.6,0,7);ctx.stroke()}
// Original geometric busts: horned guards, hooded casters, plated warriors.
ctx.fillStyle=hurt?'#f4d6b2':col;ctx.strokeStyle='#d4e8d438';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-r,r*.65);ctx.lineTo(-r*.86,-r*.1);ctx.lineTo(-r*.42,-r*.42);ctx.lineTo(r*.42,-r*.42);ctx.lineTo(r*.86,-r*.1);ctx.lineTo(r,r*.65);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#182c32';ctx.beginPath();ctx.moveTo(-r*.62,r*.68);ctx.lineTo(-r*.4,-r*.3);ctx.lineTo(0,r*.05);ctx.lineTo(r*.4,-r*.3);ctx.lineTo(r*.62,r*.68);ctx.fill();ctx.fillStyle=col;ctx.beginPath();const horns=['centaur','magnus','underlord','shadowfiend'].includes(u.id)||u.boss;ctx.moveTo(-r*.45,-r*.35);ctx.lineTo(-r*.5,-r*.9);if(horns){ctx.lineTo(-r*.8,-r*1.25);ctx.lineTo(-r*.22,-r);ctx.lineTo(0,-r*1.12);ctx.lineTo(r*.22,-r);ctx.lineTo(r*.8,-r*1.25)}else{ctx.lineTo(0,-r*1.25)}ctx.lineTo(r*.5,-r*.9);ctx.lineTo(r*.45,-r*.35);ctx.lineTo(0,-r*.17);ctx.closePath();ctx.fill();ctx.fillStyle='#eef8d9';ctx.fillRect(-r*.28,-r*.72,r*.17,2);ctx.fillRect(r*.11,-r*.72,r*.17,2);ctx.fillStyle='#0d2328';ctx.font=`600 ${small?12:16}px serif`;ctx.textAlign='center';ctx.fillText(u.symbol||'卫',0,r*.5);if(u.shield>0){ctx.strokeStyle='#9dcddd88';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,-r*.15,r*1.35,0,7);ctx.stroke()}
const bw=small?45:67,bh=4,barY=r+9;ctx.fillStyle='#102025';ctx.fillRect(-bw/2,barY,bw,bh);ctx.fillStyle=u.team==='ally'?'#8bc7a8':'#cf8c7e';ctx.fillRect(-bw/2,barY,bw*Math.max(0,u.hp/u.maxHp),bh);ctx.fillStyle='#71a7c5';ctx.fillRect(-bw/2,barY+6,bw*(u.mana||0)/100,2);ctx.fillStyle=dead?'#8d9390':'#dfe5dc';ctx.font=`${small?8:10}px 'Noto Sans SC',sans-serif`;ctx.fillText(u.name,0,barY+22);ctx.fillStyle='#8da6a6';ctx.font=`${small?6:8}px monospace`;ctx.fillText(dead?'倒下':`${Math.ceil(u.hp)} / ${Math.ceil(u.maxHp)}`,0,barY+34);if(u.stun>0){ctx.fillStyle='#ead691';ctx.font='12px sans-serif';ctx.fillText('✦',0,-r*1.6)}ctx.restore();hitboxes.push({u,x:p.x,y:p.y,r:r*1.6})}
function drawFx(t,units){fx=fx.filter(f=>t-f.created<1100);for(const f of fx){const target=units.find(u=>u.uid===f.target),source=units.find(u=>u.uid===f.source);if(!target)continue;const p=coords(target),s=source?coords(source):p,age=t-f.created,a=1-age/1100;ctx.save();ctx.globalAlpha=a;if((f.type==='damage'||f.type==='heal')&&age<240){ctx.strokeStyle=f.type==='heal'?'#a6e1bc':source?.team==='ally'?'#d1c394':'#ce8d8c';ctx.lineWidth=f.type==='heal'?2:1.3;ctx.beginPath();ctx.moveTo(s.x,s.y-10);ctx.quadraticCurveTo((s.x+p.x)/2,(s.y+p.y)/2-30,p.x,p.y-10);ctx.stroke()}ctx.textAlign='center';ctx.font=f.type==='skill'?'600 10px sans-serif':'bold 13px Georgia,serif';ctx.fillStyle=f.type==='heal'?'#a5e2bf':f.type==='skill'?'#f7d49a':f.type==='miss'?'#a8b8c3':'#f2e6c7';const txt=f.type==='skill'?f.text:f.type==='miss'?'闪避':f.type==='death'?'':f.type==='heal'?`+${f.amount}`:f.amount>0?`${f.amount}`:'吸收';ctx.fillText(txt,p.x+(f.offset||0),p.y-35-age*.035);ctx.restore()}}
function selectUnit(u){if(u.team==='ally'){openHero(u.id);return}if(u.hp<=0||battle&&battle.status!=='running')return;selected=u.uid;game.party.forEach(id=>{const hero=game.roster.find(h=>h.id===id);hero.rules=hero.rules.filter(r=>r.action!=='focus');hero.rules.unshift({condition:'always',action:'focus',target:u.uid,enabled:true});if(hero.rules.length>8)hero.rules.length=8;const active=battle?.units.find(x=>x.id===id);if(active)active.rules=JSON.parse(JSON.stringify(hero.rules))});save();toast(`全队集火：${u.name}（位置 ${u.position+1}）`);$('#battle-hint').textContent=`集火目标：敌方位置 ${u.position+1} · ${u.name}。目标倒下后自动转火。`}
canvas.addEventListener('pointerdown',e=>{const rect=canvas.getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top;const hit=hitboxes.find(h=>Math.hypot(h.x-x,h.y-y)<h.r);if(hit)selectUnit(hit.u)});
function frame(t){const dt=Math.min(.05,(t-lastFrame)/1000||0);lastFrame=t;frameEvents=[];if(!paused)visualTime+=dt*1000;if(running()&&!paused){tickBattle(battle,dt*speed);const events=battle.events.filter(e=>e.id>lastSeen);frameEvents=events;events.forEach(e=>{fx.push({...e,created:visualTime,offset:(e.id%3-1)*11});lastSeen=e.id});if(events.length){$('#battle-log').innerHTML=battle.events.slice(-40).reverse().map(e=>`<div><b>${e.time.toFixed(1)}s</b> ${escape(e.text)} ${e.amount>0?e.amount:''}</div>`).join('')}$('#clock').textContent=`${String(Math.floor(battle.time/60)).padStart(2,'0')}:${String(Math.floor(battle.time%60)).padStart(2,'0')}`;if(battle.status!=='running')finishBattle()}fx=fx.filter(f=>visualTime-f.created<1100);if(view3d){try{view3d.render({units:battle?battle.units:previewUnits(),events:frameEvents,key:battle||`preview-${game.floor}-${game.party.join('-')}`,dt:dt*speed,selected,paused})}catch(error){console.warn('3D render failed',error);view3d.dispose();view3d=null;setView('2d');toast('已安全切换 2D 战术模式。')}}if(viewMode==='2d'||!view3d)drawArena(visualTime);requestAnimationFrame(frame)}
